; sprite.asm -- chapter 23: the ball as a sprite
; generated by gen23.py
        INCLUDE "msx.inc"
        OUTPUT "sprite.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
pos     EQU VARS                ; the ball: y, then x
count   EQU VARS + 2            ; the moves left
shift   EQU VARS + 3            ; put's: x AND 7
bptr    EQU VARS + 4            ; put's: the next column of the ball
vptr    EQU VARS + 6            ; wipe's and put's: the column's VRAM address
buf     EQU VARS + $10          ; put's: a column of 16 shapes
; clash.asm's picture with the ball a hardware sprite: a move writes its Y and
; X, and nothing of the picture under it.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the picture is drawn
        VDP_REG 0, $02          ; Graphic II: 256 x 192 pixels (chapter 22)
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000, 6,144 bytes
        VDP_REG 4, $03          ; patterns           $0000, 6,144 bytes
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: every pixel paper
        ld bc, 6144
g2p:    xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2p
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld bc, 6144
g2c:    ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2c
        VRAM_WRITE $1800        ; names: 0 to 255 in each third
        ld b, 3
g2n:    xor a
g2n1:   out (VDP_DATA), a
        inc a
        jr nz, g2n1
        djnz g2n
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld hl, scpat
        ld de, $4000
        call fill               ; the scene's shapes
        ld hl, sccol
        ld de, $6000
        call fill               ; and its colours
        VRAM_WRITE $3800        ; sprite pattern 0: the ball
        ld hl, ballspr
        ld b, 32
        ld c, VDP_DATA
        otir
        VRAM_WRITE $1B00        ; sprite 0: Y, X, pattern 0, white; then the end
        ld hl, attrs
        ld b, 5
        otir
        ld bc, $1808           ; x, y
        ld (pos), bc
        VDP_REG 1, $C2          ; the display on, sprites of 16 x 16
        in a, (VDP_CTRL)        ; a flag left from before, cleared
        ld a, 64
        ld (count), a
loop:   call frame              ; the end of the paper
m0:     call move
m1:     ld hl, count
        dec (hl)
        jr nz, loop
done:   jr done

; frame: wait for the end of the paper: F, bit 7 of the status, read with the
; interrupts off (chapter 19)
frame:  in a, (VDP_CTRL)
        rla
        jr nc, frame
        ret

; move: the sprite two lines down and a pixel right: its Y and X
move:   ld hl, pos
        inc (hl)
        inc (hl)                ; y: two lines down
        inc hl
        inc (hl)                ; x: a pixel right
        VRAM_WRITE $1B00        ; sprite 0's Y and X
        ld a, (pos)
        dec a                   ; it shows a line below its Y (chapter 26)
        out (VDP_DATA), a
        ld a, (pos + 1)
        out (VDP_DATA), a
        ret

; fill: the 192 bytes of a scene table, one a line, into all 32 columns of the
; table at the VRAM address in DE (write bit included); the display is off
fill:   ld a, e
        out (VDP_CTRL), a
        ld a, d
        out (VDP_CTRL), a
        ld c, VDP_DATA
        ld d, 24                ; 24 rows of cells
.row:   ld e, 32                ; of 32 cells
.cell:  push hl
        ld b, 8
        otir                    ; a cell's eight lines
        pop hl
        dec e
        jr nz, .cell
        ld a, l
        add a, 8
        ld l, a                 ; the next row's lines (L = y)
        dec d
        jr nz, .row
        ret

; the scene: for every line of the screen a byte of shape and a byte of colour,
; the same in every column; each table a page of its own, so that L = y
        ALIGN 256
scpat:
        db $10, $54, $00, $00, $01, $45, $00, $00, $10, $54, $00, $00, $01, $45, $00, $00
        db $10, $54, $00, $00, $01, $45, $00, $00, $10, $54, $00, $00, $01, $45, $00, $00
        db $10, $54, $00, $00, $01, $45, $00, $00, $10, $54, $00, $00, $01, $45, $00, $00
        db $10, $54, $00, $00, $01, $45, $00, $00, $10, $54, $00, $00, $01, $45, $00, $00
        db $10, $54, $00, $00, $01, $45, $00, $00, $10, $54, $00, $00, $01, $45, $00, $00
        db $10, $54, $00, $00, $01, $45, $00, $00, $10, $54, $00, $00, $01, $45, $00, $00
        db $10, $54, $00, $00, $01, $45, $00, $00, $10, $54, $00, $00, $01, $45, $00, $00
        db $10, $54, $00, $00, $01, $45, $00, $00, $10, $54, $00, $00, $01, $45, $00, $00
        db $10, $54, $00, $00, $01, $45, $00, $00, $10, $54, $00, $00, $01, $45, $00, $00
        db $10, $54, $00, $00, $01, $45, $00, $00, $10, $54, $00, $00, $01, $45, $00, $00
        db $10, $54, $00, $00, $01, $45, $00, $00, $10, $54, $00, $00, $01, $45, $00, $00
        db $10, $54, $00, $00, $01, $45, $00, $00, $10, $54, $00, $00, $01, $45, $00, $00
        db $10, $54, $00, $00, $01, $45, $00, $00, $10, $54, $00, $00, $01, $45, $00, $00
        ALIGN 256
sccol:
        db $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13
        db $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13
        db $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13
        db $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13
        db $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13
        db $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13
        db $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13
        db $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13
        db $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13
        db $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13
        db $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13
        db $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13
        db $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13, $13
ballspr:                        ; the ball as a sprite (chapter 26)
        db $03, $0F, $1F, $3F, $7F, $7F, $FF, $FF, $FF, $FF, $7F, $7F, $3F, $1F, $0F, $03
        db $C0, $F0, $F8, $FC, $FE, $FE, $FF, $FF, $FF, $FF, $FE, $FE, $FC, $F8, $F0, $C0
attrs:  db $07, $18, 0, $0F, $D0
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
